import React from "react";

function InputForm({ formData, handleChange, handleSubmit }) {
  return (
    <div>
      <h2>📥 Enter Student Data</h2>

      <label>High School Average</label>
      <input name="hs_avg" placeholder="High School Avg" onChange={handleChange} /><br /><br />
      <label>First Term GPA</label>
      <input name="first_term_gpa" placeholder="First Term GPA" onChange={handleChange} /><br /><br />
      <label>Math Score</label>
      <input name="math_score" placeholder="Math Score" onChange={handleChange} /><br /><br />
      <label>English Geade</label>
      <input name="english_grade" placeholder="English Grade" onChange={handleChange} /><br /><br />

      <button onClick={handleSubmit}>Predict</button>
    </div>
  );
}

export default InputForm;
